CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE IF NOT EXISTS terminals (id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK (status IN ('active','inactive','offline')),tags JSONB NOT NULL DEFAULT '{}'::jsonb,last_seen_at TIMESTAMPTZ,last_latitude DOUBLE PRECISION,last_longitude DOUBLE PRECISION,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS geofences (id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',type TEXT NOT NULL CHECK (type IN ('circle','polygon')),mode TEXT NOT NULL CHECK (mode IN ('active','paused')),center GEOGRAPHY(POINT,4326),radius_m DOUBLE PRECISION,geometry GEOGRAPHY(POLYGON,4326),tags JSONB NOT NULL DEFAULT '{}'::jsonb,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_geofences_geometry ON geofences USING GIST (geometry);
CREATE TABLE IF NOT EXISTS locations (id TEXT PRIMARY KEY,terminal_id TEXT NOT NULL REFERENCES terminals(id),point GEOGRAPHY(POINT,4326) NOT NULL,accuracy_m DOUBLE PRECISION NOT NULL DEFAULT 0,speed_mps DOUBLE PRECISION NOT NULL DEFAULT 0,heading DOUBLE PRECISION NOT NULL DEFAULT 0,observed_at TIMESTAMPTZ NOT NULL,received_at TIMESTAMPTZ NOT NULL,attributes JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS idx_locations_terminal_time ON locations (terminal_id, observed_at DESC);
CREATE TABLE IF NOT EXISTS geofence_events (id TEXT PRIMARY KEY,deduplication_key TEXT NOT NULL UNIQUE,terminal_id TEXT NOT NULL REFERENCES terminals(id),geofence_id TEXT NOT NULL REFERENCES geofences(id),type TEXT NOT NULL CHECK (type IN ('enter','exit','dwell','crossing')),status TEXT NOT NULL CHECK (status IN ('open','acknowledged','closed')),location_id TEXT REFERENCES locations(id),detected_at TIMESTAMPTZ NOT NULL,acknowledged_at TIMESTAMPTZ,closed_at TIMESTAMPTZ,metadata JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS idx_events_terminal_time ON geofence_events (terminal_id, detected_at DESC);
CREATE INDEX IF NOT EXISTS idx_events_geofence_time ON geofence_events (geofence_id, detected_at DESC);
CREATE TABLE IF NOT EXISTS subscriptions (id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,event_types JSONB NOT NULL DEFAULT '[]'::jsonb,terminal_tags JSONB NOT NULL DEFAULT '{}'::jsonb,geofence_ids JSONB NOT NULL DEFAULT '[]'::jsonb,secret TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_deliveries (id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES subscriptions(id),event_id TEXT NOT NULL REFERENCES geofence_events(id),status TEXT NOT NULL,attempt INTEGER NOT NULL DEFAULT 0,http_status INTEGER,error TEXT,created_at TIMESTAMPTZ NOT NULL,sent_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_deliveries_subscription_time ON webhook_deliveries (subscription_id, created_at DESC);
